import json
G=[[0]*30 for _ in range(30)]
M=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for tr in range(4):
 for tc in range(4):
  y=1+7*tr; x=1+7*tc
  for dy in range(5):
   for dx in range(5): G[y+dy][x+dx]=4 if dy in (0,4) or dx in (0,4) else M[tr][tc]
# horizontal connectors across all tile-column separators between extreme equal-color blocks
for color, positions in [(3,[(0,0),(0,3),(2,0),(2,3)]),(8,[(1,1),(1,2),(3,1),(3,2)])]:
 for tr in sorted(set(r for r,c in positions)):
  cs=[c for r,c in positions if r==tr]
  if len(cs)>=2:
   lo,hi=min(cs),max(cs)
   for tc in range(lo,hi):
    for y in range(1+7*tr+1,1+7*tr+4):
     for x in (1+7*tc+5,1+7*tc+6): G[y][x]=color
 # vertical connections
 for tc in sorted(set(c for r,c in positions)):
  rs=[r for r,c in positions if c==tc]
  if len(rs)>=2:
   lo,hi=min(rs),max(rs)
   for tr in range(lo,hi):
    for x in range(1+7*tc+1,1+7*tc+4):
     for y in (1+7*tr+5,1+7*tr+6): G[y][x]=color
print(json.dumps({'action':'submit','grid':G}))
